      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Darifenacin, a piperidine-phenethyl drug, had a rat Kp,free of 0.02 after subcutaneous dosing, showing that even non-acid piperidine-phenethyl structures can have very low unbound brain exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Bepotastine and olopatadine, both carboxylic-acid-containing piperidines, had brain ISF concentrations lower than unbound plasma in mice, directly showing limited brain distribution for this acid-containing class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "MDL 105725, a polar piperidine metabolite, achieved brain ECF/plasma AUC ratios below 0.25 after i.v. dosing, indicating that polar piperidine structures can have poor CNS penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "A benzimidazole-piperidine analogue without the carboxylic acid showed a brain/plasma ratio of 2.7 in rats, demonstrating that the benzimidazole core can penetrate the BBB when the acid/zwitterion is absent.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C16"],
      "claim": "MDL 100907, a piperidine without the acid, showed a brain ECF/plasma AUC ratio of 1.01 after oral dosing, confirming that non-acid piperidines can have good CNS access.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C11"],
      "claim": "A benzimidazole-containing compound reached 13 µM in rat brain after IP dosing, supporting CNS access for benzimidazoles, but it lacks the query's carboxylic acid.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a zwitterionic benzimidazole-piperidine bearing the same Ar-C(CH3)2COOH acid motif as fexofenadine, which has only 2% unbound brain-to-plasma ratio in rodents. Additional acid-containing piperidines such as bepotastine show low brain ISF, and darifenacin shows very low Kp,free. The benzimidazole/piperidine CNS-penetrant analogues all lack the carboxylic acid and therefore do not override the acid/zwitterion liability. Prediction: fail.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF data for the exact query or an acid-containing benzimidazole analogue.",
